static readonly SemaphoreSlim _gate = new(1, 1);   // свободно 1 место из 1

await _gate.WaitAsync();   // место есть → сразу; нет → ждём, поток свободен
try
{
    await WriteToFileAsync(data);   // внутри только мы
}
finally
{
    _gate.Release();       // место — следующему ожидающему
}

