async Task SaveAsync()
{
    await _gate.WaitAsync();            // 1) место взято, счётчик 0
    try     { await FlushAsync(); }     // 2) ждём FlushAsync…
    finally { _gate.Release(); }        // 3) …а до Release не дойдём
}
async Task FlushAsync()
{
    await _gate.WaitAsync();            // 2) места нет — ждём вечно
    try     { await WriteAsync(); }
    finally { _gate.Release(); }
}

